package app.unifeed.chat;
import java.security.Principal; import java.time.Instant; import java.util.UUID; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.messaging.handler.annotation.*; import org.springframework.messaging.simp.SimpMessagingTemplate; import org.springframework.stereotype.Controller; import org.springframework.transaction.annotation.Transactional;
@Controller public class ChatController {private final JdbcTemplate jdbc;private final SimpMessagingTemplate ws;public ChatController(JdbcTemplate j,SimpMessagingTemplate w){jdbc=j;ws=w;}
 @MessageMapping("/chat.send/{threadId}") @Transactional public void send(@DestinationVariable UUID threadId,ChatMessage input,Principal principal){UUID sender=UUID.fromString(principal.getName());Integer member=jdbc.queryForObject("SELECT count(*) FROM thread_participants WHERE thread_id=? AND user_id=?",Integer.class,threadId,sender);if(member==null||member==0)throw new IllegalStateException("Not a thread participant");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO direct_messages(id,thread_id,sender_id,content) VALUES(?,?,?,?)",id,threadId,sender,input.content);ws.convertAndSend("/topic/chat/"+threadId,new MessageDto(id,threadId,sender,input.content,Instant.now()));}
 public record ChatMessage(String content){} public record MessageDto(UUID id,UUID threadId,UUID senderId,String content,Instant sentAt){}
 @org.springframework.web.bind.annotation.GetMapping("/api/v1/chat/threads/{threadId}/messages") @org.springframework.web.bind.annotation.ResponseBody public java.util.List<java.util.Map<String,Object>> history(@org.springframework.web.bind.annotation.PathVariable UUID threadId,Principal principal){UUID user=UUID.fromString(principal.getName());Integer member=jdbc.queryForObject("SELECT count(*) FROM thread_participants WHERE thread_id=? AND user_id=?",Integer.class,threadId,user);if(member==null||member==0)throw new IllegalStateException("Not a thread participant");return jdbc.queryForList("SELECT id,sender_id,content,created_at,read_at FROM direct_messages WHERE thread_id=? AND deleted_at IS NULL ORDER BY created_at DESC LIMIT 100",threadId);}
}
